#!/usr/bin/env bash
G="$(cd "$(dirname "$0")" && pwd)/genref.sh"
cd "$(dirname "$0")/../../../.."
RM=design/ring-master; M=design/assets/v1/masters; H=design/assets/v1/home
SET=$M/E-03-moss-rock-set.png; R4=$RM/04-three-quarter-outer.png; R8=$RM/08-flat-45.png
run(){ [[ -f "$2" ]] && { echo "SKIP $2"; return; }; "$G" "$@" || echo "FAIL $2"; }
BASE="Real product still-life photograph on a hand-built natural studio set, not a 3D render. Keep the same set as the attached set reference: a rounded pale granite rock with warm rust-tinted mineral patches sitting in a dense bed of real green cushion moss, soft out-of-focus fern fronds at a foreground edge, and a warm cream plaster wall behind with soft leaf shadows cast by sunlight through plants. Medium-format camera, 100 mm macro lens, true-to-life color, warm natural grade, soft film-like tonality, fine grain, real organic imperfections."
RING="The smart ring must match the attached ring reference exactly: smooth domed band about 7 mm wide, thin bright chamfered edges, black matte inner shell with two small square sensor windows and two small GREY OVAL contact pads (not gold dots), sensors not lit. The ring rests physically on its surface with a clear contact shadow, never floating. Its polished surface reflects only the cream wall, moss and warm light, never a landscape, sky or trees."
AVOID="Avoid: CGI or plastic look, HDR, neon or oversaturated green, floating ring, stacked stones, mossy log pedestal, gradient backdrop, flowers, water droplets, marble, lens flare, bokeh particles, vignette, text, logos, people, hands, extra jewelry."
# Wave 1: bases and hero
run "$BASE 06:40 dawn. Low, pale-gold dawn sun from the far left, about 3400K; the leaf shadows on the wall are long, soft and stretched diagonally, overall light gentle and slightly hazy. The silver ring lies on its side on the flat top of the rock. Wide 16:9, camera at rock height. Rock, moss and ring sit in the right third; the left half is calm cream wall with faint long leaf shadows, empty for a headline. $RING $AVOID" $H/A-01-hero-desktop.png --size 1536x864 --ref $SET --ref $R8 &
run "$BASE 06:40 dawn. Low, pale-gold dawn sun from the far left, about 3400K; leaf shadows on the wall long, soft and stretched. The silver ring lies on its side on the flat top of the rock. Vertical 3:4: rock, moss and ring in the lower third, the upper part calm cream wall with faint leaf shadows for a headline. $RING $AVOID" $H/A-01-hero-mobile.png --size 1152x1536 --ref $SET --ref $R8 &
run "$BASE Fixed, locked-off camera at 09:00. Crisp clear morning sun from the left, about 5000K; leaf shadows on the wall are sharp-edged and fall diagonally toward the right. The silver ring stands upright at a three-quarter angle on the top of the rock. Wide 16:9, ring and rock centered-left, generous wall area showing the leaf shadows clearly. $RING $AVOID" $H/A-06a-set-0900.png --size 1536x864 --ref $SET --ref $R4 &
run "$BASE Product shot, Daylight. Soft even open daylight from the left, about 5500K, leaf shadows on the wall soft and subtle. The silver ring stands upright at a three-quarter angle on the flat top of the rock, slightly left of center, with plenty of calm space around it. 4:3, eye-level with the ring. $RING $AVOID" $H/P-01-silver-daylight.png --size 1536x1152 --ref $SET --ref $R4 &
wait
# Wave 2: independent scenes
run "$BASE Early morning, about 07:00, cool soft pale light just after sunrise, about 4800K, leaf shadows faint and diffuse. The silver ring rests on its side directly on the soft green moss bed at the foot of the rock, slightly sunk into the moss, calm and still like waking. 4:3, close and low, ring in the lower left third, quiet space above. $RING $AVOID" $H/A-02-sleep.png --size 1536x1152 --ref $SET --ref $R8 &
run "$BASE Mid-morning, about 10:00, bright fresh sun from the upper left, about 5200K, crisp leaf shadows on the wall. The silver ring stands upright on a small flat piece of pale stone set into the moss in front of the main rock. 4:3, camera slightly above, ring right of center. $RING $AVOID" $H/A-03-context-1000.png --size 1536x1152 --ref $SET --ref $R4 &
run "$BASE Midday, about 12:30, high overhead sun, about 5600K, short crisp leaf shadows falling almost straight down the wall and dappling the moss. Top-down view at about 75 degrees onto the flat top of the rock, where the silver ring lies on its side, dappled light crossing it. 4:3, ring slightly off-center. $RING $AVOID" $H/A-05-context-1230.png --size 1536x1152 --ref $SET --ref $R8 &
run "$BASE Late afternoon, 17:30, warm low golden sun from the right, about 3800K, long warm leaf shadows. A modern smartphone lies flat, screen up, on a broad flat slab of pale stone set into the moss; the silver ring lies on its side on the stone right next to the phone. The phone screen is a flat, evenly lit plain light-grey screen with no interface at all, for later compositing, no glare. 4:3, camera about 55 degrees from above, phone center-right. $RING $AVOID" $H/A-07-insight-phone.png --size 1536x1152 --ref $SET --ref $R8 &
wait
# Wave 3: material, package, night
run "$BASE Macro, early evening 18:00, warm side light about 3800K. The silver ring stands upright on the edge of the rock; focus on the domed polished outer surface and the thin chamfered edge highlight; moss and cream wall fall softly out of focus. 1:1, ring slightly left. $RING $AVOID" $H/A-08-macro-outer.png --size 1024x1024 --ref $SET --ref $R4 &
run "Macro photograph looking into the inside of the silver smart ring lying on its side on the pale granite rock from the set reference, moss softly out of focus behind: black matte inner shell, two small dark square sensor windows and two small grey oval contact pads, sensors NOT lit. Warm evening side light about 3800K grazes the inner surface. 1:1, 100 mm macro look, real photograph. $AVOID" $H/A-09-macro-inner.png --size 1024x1024 --ref $RM/07-macro-sensors.png --ref $SET &
run "$BASE 18:30 low sun. The silver ring lies flat on the broad, fairly flat top of the pale granite rock. One hard sun source from a very low angle, about 10 to 15 degrees, around 4300K, casts a single long elliptical shadow across the rock: sharp at the contact point, softening with distance; a small glint from the polished inner edge falls inside the shadow, consistent with the light. Moss visible only at the far edges. Camera about 65 degrees from above. Ring in the left third, shadow flowing into open stone on the right. 16:9. $RING $AVOID Also avoid: more than one shadow." $H/A-10-ring-shadow.png --size 1536x864 --ref $SET --ref $R8 &
run "$BASE 19:30, warm lamp-like low light from the upper right, about 2900K. Top-down view of a broad flat slab of pale stone set into the moss, with calm even spacing: the silver ring lying flat, the round warm-white charging dock with its white cable loosely coiled, and the sizing kit card tray with eight grey sizing rings, all exactly as in the attached product reference. Moss frames the slab edges. 4:3, objects slightly left of center. No box, no manual. $RING $AVOID" $H/A-11-package-flatlay.png --size 1536x1152 --ref $SET --ref $R8 --ref $M/R-kit.png &
wait
run "$BASE Night, 23:00. The same set, now lit only by faint cool blue-ink moonlight from the left and a very dim warm glow at the edge of the round warm-white charging dock. The silver ring sits in the charging dock (from the attached product reference) on the flat top of the rock. Deep blue-black tones around #151820, the wall dark with barely visible leaf shadows, ring readable with one soft highlight. Wide 16:9, rock and dock in the right third, large calm dark space on the left for a closing line. $RING $AVOID" $H/A-12-night-desktop.png --size 1536x864 --ref $SET --ref $R4 --ref $M/R-kit.png &
run "$BASE Night, 23:00. Lit only by faint cool blue-ink moonlight and a very dim warm glow at the edge of the round warm-white charging dock. The silver ring sits in the charging dock (from the attached product reference) on the flat top of the rock. Deep blue-black tones around #151820, ring readable with one soft highlight. Vertical 3:4: rock and dock in the lower third, dark calm space above. $RING $AVOID" $H/A-12-night-mobile.png --size 1152x1536 --ref $SET --ref $R4 --ref $M/R-kit.png &
# Edits from bases
run "Keep this exact image: same camera, framing, set, and ring position. Change only the time of day to 15:00: warm sun now from the right, about 4200K, leaf shadows on the wall shift to fall diagonally toward the left, slightly softer and warmer. Nothing else changes. No text." $H/A-06b-set-1500.png --size 1536x864 --ref $H/A-06a-set-0900.png &
run "Keep this exact image. Change only the lighting to a single warm tungsten lamp from the right, about 2900K, evening mood: warmer highlights on the ring, deeper soft shadow falling to the left, the wall a little darker; keep colors natural, not orange-saturated, so the silver still reads as cool silver. Same camera, ring, set, and position. No text." $H/P-02-silver-lamp.png --size 1536x1152 --ref $H/P-01-silver-daylight.png &
wait
run "Keep this exact image (first attached). Replace only the ring's outer finish with the satin matte black finish shown in the second attached reference, dark brushed chamfered edges. Same geometry, camera, framing, light, set, shadow, and position. No text." $H/P-03-black-daylight.png --size 1536x1152 --ref $H/P-01-silver-daylight.png --ref $M/R-black.png &
run "Keep this exact image (first attached). Replace only the ring's outer finish with the polished warm champagne gold finish shown in the second attached reference, gold chamfered edges, black inner shell unchanged. Same geometry, camera, framing, light, set, shadow, and position. No text." $H/P-05-gold-daylight.png --size 1536x1152 --ref $H/P-01-silver-daylight.png --ref $M/R-gold.png &
run "Keep this exact image (first attached). Replace only the ring's outer finish with the satin matte black finish shown in the second attached reference, dark brushed chamfered edges. Same geometry, camera, framing, warm lamp light, set, shadow, and position. No text." $H/P-04-black-lamp.png --size 1536x1152 --ref $H/P-02-silver-lamp.png --ref $M/R-black.png &
run "Keep this exact image (first attached). Replace only the ring's outer finish with the polished warm champagne gold finish shown in the second attached reference, gold chamfered edges, black inner shell unchanged. Same geometry, camera, framing, warm lamp light, set, shadow, and position. No text." $H/P-06-gold-lamp.png --size 1536x1152 --ref $H/P-02-silver-lamp.png --ref $M/R-gold.png &
wait
echo MOSS ALL DONE
